-- Athena saved query (Product_B2C_Intl)
-- ID: f061b304-3059-49d8-9eca-a6722944f684
-- Name: Cohorted deal final metrics Click and order share - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH date_params AS ( SELECT TIMESTAMP '2026-04-15 18:30:00' AS start_time, TIMESTAMP '2026-04-16 18:30:00' AS end_time ), srp AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, mri_session_id, route_id, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, MAX(CASE WHEN cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END) AS boostui_seen FROM user_interaction.search_route_details s CROSS JOIN date_params d WHERE s.__time >= d.start_time AND s.__time < d.end_time AND channel = 'MOBILE_APP' AND os = 'iOS' AND tp_channel = 'INVALID' AND country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), doj) = 0 GROUP BY 1,2,3,4 ), red_deal_rids AS ( SELECT DISTINCT exp_variant, route_id FROM srp WHERE boostui_seen = 1 ), boosted_sessions AS ( SELECT DISTINCT mri_session_id FROM srp WHERE boostui_seen = 1 ), sl_ranked AS ( SELECT s.*, ROW_NUMBER() OVER ( PARTITION BY mri_session_id, route_id, mri_uuid ORDER BY __time DESC ) AS rn FROM user_interaction.seat_layout_details s CROSS JOIN date_params d WHERE s.__time >= d.start_time AND s.__time < d.end_time AND os = 'iOS' AND country = 'IND' AND DATE(DATE_ADD('MINUTE', 330, __time)) = CAST(doj AS DATE) ), sl AS ( SELECT mri_session_id, route_id, __time, mri_uuid, CASE WHEN user_origin LIKE 'BOOSTUI%' THEN 1 ELSE 0 END AS sl_entry, 1 AS sl_click -- treat each row as 1 click FROM sl_ranked WHERE rn = 1 ), confirm_ranked AS ( SELECT * FROM ( SELECT c.*, sl.sl_entry, ROW_NUMBER() OVER ( PARTITION BY c.tin ORDER BY sl.__time DESC ) AS rn FROM user_interaction.confirm_order_details c LEFT JOIN sl ON c.mri_session_id = sl.mri_session_id AND c.route_id = sl.route_id CROSS JOIN date_params d WHERE c.__time >= d.start_time AND c.__time < d.end_time AND c.os = 'iOS' AND c.country = 'IND' AND DATE(DATE_ADD('MINUTE', 330, c.__time)) = CAST(c.doj AS DATE) AND c.status = 200 AND c.tin IS NOT NULL AND c.tin NOT IN ('', 'null') ) WHERE rn = 1 ) SELECT srp.doi, srp.exp_variant, --Click Share Instances -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 -- THEN sl.mri_uuid END) AS boosted_boosted_sl_clicks, -- COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL AND rdr.route_id IS NOT NULL -- THEN sl.mri_uuid END) AS boosted_offer_tuple_sl_clicks, -- COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL -- THEN sl.mri_uuid END) AS boosted_overall_sl_clicks, -- COUNT(DISTINCT CASE WHEN rdr.route_id IS NOT NULL -- THEN sl.mri_uuid END) AS overall_offer_tuple_sl_clicks, -- COUNT(DISTINCT sl.mri_uuid) AS overall_overall_sl_clicks, -- Universe of SL lands across platform -- -- Order Share Instances -- COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL AND rdr.route_id IS NOT NULL -- THEN c.tin END) AS boosted_offer_tuple_tins, -- COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL -- THEN c.tin END) AS boosted_overall_tins, -- COUNT(DISTINCT CASE WHEN rdr.route_id IS NOT NULL -- THEN c.tin END) AS overall_offer_tuple_tins, -- COUNT(DISTINCT c.tin) AS overall_overall_tins, --Click Share session COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 THEN sl.mri_session_id END) AS boosted_boosted_sl_sessions, COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL AND rdr.route_id IS NOT NULL THEN sl.mri_session_id END) AS boosted_offer_tuple_sl_sessions, COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL THEN sl.mri_session_id END) AS boosted_overall_sl_sessions, COUNT(DISTINCT CASE WHEN rdr.route_id IS NOT NULL THEN sl.mri_session_id END) AS overall_offer_tuple_sl_sessions, COUNT(DISTINCT sl.mri_session_id) AS overall_overall_sl_sessions, -- Universe of SL lands across platform -- Order Share Instances COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL AND rdr.route_id IS NOT NULL THEN c.mri_session_id END) AS boosted_offer_tuple_tins, COUNT(DISTINCT CASE WHEN bs.mri_session_id IS NOT NULL THEN c.mri_session_id END) AS boosted_overall_tins, COUNT(DISTINCT CASE WHEN rdr.route_id IS NOT NULL THEN c.mri_session_id END) AS overall_offer_tuple_tins, COUNT(DISTINCT c.mri_session_id) AS overall_overall_tins -- CASE -- WHEN bs.mri_session_id IS NOT NULL THEN 'Seen' -- ELSE 'Not Seen' -- END AS boostui_seen, -- -- CASE WHEN rdr.route_id IS NULL THEN 'non-Offer Tuple' ELSE 'Offer Tuple' END AS tuple_cohort, -- -- boosted route universe -- COUNT(DISTINCT rdr.route_id) AS boosted_routeids, -- -- search sessions -- COUNT(DISTINCT srp.mri_session_id) AS search_sessions, -- -- COUNT(DISTINCT CASE WHEN srp.boostui_seen = 1 THEN srp.mri_session_id END) AS boosted_search_sessions, -- -- COUNT(DISTINCT CASE WHEN srp.boostui_seen = 0 THEN srp.mri_session_id END) AS non_boosted_search_sessions, -- -- SL clicks -- COUNT(DISTINCT sl.mri_uuid) AS overall_sl_clicks, -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 AND rdr.route_id IS NOT NULL THEN sl.mri_uuid END) AS offer_tuple_boosted_sl_clicks, -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 0 AND rdr.route_id IS NOT NULL THEN sl.mri_uuid END) AS offer_tuple_non_boosted_sl_clicks, -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 THEN sl.mri_uuid END) AS overall_boosted_sl_clicks, -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 0 THEN sl.mri_uuid END) AS overall_non_boosted_sl_clicks, -- -- confirm tins -- COUNT(DISTINCT c.tin) AS overall_confirm_sessions, -- -- COUNT(DISTINCT CASE WHEN c.sl_entry = 1 THEN c.tin END) AS boosted_confirm_tin, -- -- COUNT(DISTINCT CASE WHEN c.sl_entry = 0 THEN c.tin END) AS non_boosted_confirm_tin, -- -- SL sessions -- COUNT(DISTINCT sl.mri_session_id) AS overall_sl_sessions, -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 THEN sl.mri_session_id END) AS boosted_sl_sessions, -- COUNT(DISTINCT CASE WHEN sl.sl_entry = 0 THEN sl.mri_session_id END) AS non_boosted_sl_sessions, -- -- confirm sessions -- COUNT(DISTINCT c.mri_session_id) AS overall_confirm_sessions -- COUNT(DISTINCT CASE WHEN c.sl_entry = 1 THEN c.mri_session_id END) AS boosted_confirm_sessions, -- COUNT(DISTINCT CASE WHEN c.sl_entry = 0 THEN c.mri_session_id END) AS non_boosted_confirm_sessions FROM srp LEFT JOIN red_deal_rids rdr ON rdr.exp_variant = srp.exp_variant AND rdr.route_id = srp.route_id LEFT JOIN boosted_sessions bs ON bs.mri_session_id = srp.mri_session_id LEFT JOIN sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN confirm_ranked c ON srp.mri_session_id = c.mri_session_id AND srp.route_id = c.route_id WHERE srp.exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1, 2 -- ,3,4 ORDER BY 2 -- ,3 DESC, 4 DESC
